import{_ as i,C as n,c as l,o as t,j as s,b as u,a2 as c,a,w as o,G as d,a3 as m}from"./chunks/framework.DkPtUiZm.js";const C=JSON.parse('{"title":"Tous les composants dans la démo mobile","description":"","frontmatter":{},"headers":[],"relativePath":"guides/catalogue-mobile.md","filePath":"guides/catalogue-mobile.md","lastUpdated":1795096530000}'),p={name:"guides/catalogue-mobile.md"};function h(g,e,v,b,f,L){const r=n("Mermaid");return t(),l("div",null,[e[1]||(e[1]=s("h1",{id:"tous-les-composants-dans-la-demo-mobile",tabindex:"-1"},[a("Tous les composants dans la démo mobile "),s("a",{class:"header-anchor",href:"#tous-les-composants-dans-la-demo-mobile","aria-label":'Permalink to "Tous les composants dans la démo mobile"'},"​")],-1)),e[2]||(e[2]=s("p",null,[a("L’entrée "),s("strong",null,"Composants → Tous"),a(" ("),s("code",null,"/components"),a(") est maintenant le catalogue général. Elle montre les composants déjà présents dans le code natif, avec aperçu, famille, statut de couverture et lien vers les variantes ou le parcours complet.")],-1)),(t(),u(m,null,{default:o(()=>[d(r,{id:"mermaid-6",class:"mermaid",graph:"flowchart%20LR%0A%20%20Inventory%5B%22Inventaire%20central%20des%20composants%22%5D%20--%3E%20Search%5B%22Recherche%20par%20nom%2C%20alias%20et%20description%22%5D%0A%20%20Family%5B%22Tous%20ou%20famille%20choisie%22%5D%20--%3E%20Search%0A%20%20Search%20--%3E%20List%5B%22Liste%20virtualis%C3%A9e%20de%20fiches%22%5D%0A%20%20List%20--%3E%20Preview%5B%22Aper%C3%A7u%20local%20du%20composant%22%5D%0A%20%20List%20--%3E%20Integration%5B%22Brique%20utilis%C3%A9e%20dans%20un%20parcours%20complet%22%5D%0A%20%20Preview%20--%3E%20Examples%5B%22%C3%89cran%20des%20variantes%22%5D%0A%20%20Integration%20--%3E%20Examples%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=c('<h2 id="utilisation" tabindex="-1">Utilisation <a class="header-anchor" href="#utilisation" aria-label="Permalink to &quot;Utilisation&quot;">​</a></h2><ol><li>Ouvrir <strong>Composants</strong> dans la barre basse, ou <strong>Composants → Tous</strong> dans le menu.</li><li>Parcourir les aperçus : boutons, badges, avatars, spinners, champs, dates, navigation, menus, états et affichages métier.</li><li>Rechercher un nom (<code>Spinner</code>), un sous-composant (<code>TabsTrigger</code>, <code>FormField</code>), un mot français ou une description. La recherche ignore la casse et les accents.</li><li>Filtrer par famille : Fondations, Saisie, Dates, Navigation, Actions, Retours, Métier ou Intégration. <strong>Tous</strong> retire le filtre de famille.</li><li>Toucher <strong>Voir les variantes</strong> pour les exemples détaillés. Les briques comme AppShell, CrudPage ou RequireSession proposent <strong>Ouvrir le parcours</strong>.</li><li>Vérifier clair/sombre, couleurs et mouvement réduit via Personnaliser, sans quitter le catalogue. Un résultat vide propose de réinitialiser la recherche.</li></ol><p>Les contrôles simples sont interactifs et les valeurs restent locales à l’aperçu. Les aperçus historiques de champs texte sont en lecture seule ; les nouveaux éditeurs et champs avancés sont aussi interactifs. Leur lien ouvre les écrans adaptés aux essais de saisie et de clavier. Les notifications réutilisent le Toaster de la démo. Les fichiers/images passent par l’adaptateur déjà configuré et ne sont jamais envoyés à un serveur par le catalogue.</p><h2 id="lecture-des-statuts" tabindex="-1">Lecture des statuts <a class="header-anchor" href="#lecture-des-statuts" aria-label="Permalink to &quot;Lecture des statuts&quot;">​</a></h2><ul><li><strong>Disponible</strong> : la responsabilité principale du composant existe sur mobile.</li><li><strong>Partiel</strong> : une partie du contrat web reste absente ; la description nomme les écarts réels. Le lot du 17 novembre a complété les fiches auparavant partielles.</li><li><strong>Brique mobile</strong> : composant ou assemblage exposé pour les usages natifs.</li></ul><p>Ces statuts ne signifient pas une parité de toutes les props web ni une validation sur tous les appareils. Le compteur indique des <strong>fiches</strong>, pas les 115 modules publics comparés dans la <a href="./../contribuer/parite-web-mobile.html">matrice web/mobile</a>. Une fiche peut regrouper des parties composables, par exemple CardHeader/CardBody/ CardFooter ou TabsList/TabsTrigger/TabsContent. Les noms apparentés sont recherchables. Les composants encore à créer ne sont pas présentés comme disponibles.</p><h2 id="organisation-et-maintenance" tabindex="-1">Organisation et maintenance <a class="header-anchor" href="#organisation-et-maintenance" aria-label="Permalink to &quot;Organisation et maintenance&quot;">​</a></h2><p><code>apps/native-demo/demo/component-catalogue.ts</code> contient l’inventaire, les familles, les limites et les destinations. <code>ComponentPreview.tsx</code> compose les aperçus à partir des vrais composants natifs. <code>AllComponentsScreen.tsx</code> applique recherche et filtres et rend les fiches dans une FlatList. La recherche reste montée pendant les mises à jour de la liste ; les catégories et compteurs restent au-dessus du défilement.</p><p>La liste ne monte pas tous les formulaires et toutes les applications en même temps. Les ensembles liés à la session, au routage ou à une source de données sont signalés comme intégrations et renvoient vers l’exemple où ils sont réellement utilisés. Les états d’aperçu peuvent être réinitialisés lors de la virtualisation des fiches.</p><p>Lorsqu’un composant public est ajouté, mettre à jour inventaire, aperçu, limite et lien. Les tests vérifient la couverture des composants exportés de l’entrée native, les noms uniques, la recherche, l’existence des destinations et le montage de chaque aperçu sous SiaNativeProvider. Ils ne remplacent pas les essais de clavier, de lecteur d’écran et de défilement sur téléphone.</p><h2 id="acces-au-theme-et-cout-des-mises-a-jour" tabindex="-1">Accès au thème et coût des mises à jour <a class="header-anchor" href="#acces-au-theme-et-cout-des-mises-a-jour" aria-label="Permalink to &quot;Accès au thème et coût des mises à jour&quot;">​</a></h2><p>Le bouton soleil/lune de l’en-tête bascule directement entre clair et sombre ; la roue dentée garde les réglages détaillés et le mode Système. Le choix est conservé par les préférences de la démo.</p><p>Les fiches sont mémorisées dans CatalogueCard ; renderItem, les clés et le callback d’ouverture des variantes sont stables. Une mise à jour des contrôles ne recalcule pas tous les aperçus inchangés. Les états des fiches et les mises à jour de thème restent actifs. La virtualisation est conservée, sans getItemLayout fictif pour des hauteurs variables ni suppression des avertissements de VirtualizedList.</p><p>Les valeurs dt de cet avertissement correspondent à des intervalles entre événements et ne mesurent pas seules le temps de calcul d’une fiche. Les essais de défilement sur de vrais appareils restent nécessaires pour mesurer la fluidité.</p><p>Les nouvelles API et leurs limites sont détaillées dans les <a href="./complements-mobiles.html">compléments mobiles</a>. Le catalogue compte désormais 123 fiches, dont Icons avec les 41 tracés partagés et la page Boutons et icônes.</p><p>Les <a href="./nouveaux-composants-mobiles.html">17 nouveaux modules</a> disposent de leurs propres écrans de périodes, sécurité/suivi, agenda et journal d’activité.</p><p>Les 13 <a href="./adaptations-mobiles.html">adaptations mobiles</a> sont accessibles dans Tous et sur leur écran dédié, avec six rubriques.</p>',17))])}const T=i(p,[["render",h]]);export{C as __pageData,T as default};
